import{z as B,x as p,o as s,c as A,q as r,j as E,D as o,d as e,s as l,S as i,b as n}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"香农容量在链路","description":"","frontmatter":{"title":"香农容量在链路","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shannon-capacity-link.md","filePath":"cs/shannon-capacity-link.md","lastUpdated":1791063341000}'),d={name:"cs/shannon-capacity-link.md"};function C(m,a,c,h,u,f){const t=p("Mermaid");return s(),A("div",null,[a[2]||(a[2]=r('<h1 id="香农容量在链路" tabindex="-1">香农容量在链路 <a class="header-anchor" href="#香农容量在链路" aria-label="Permalink to &quot;香农容量在链路&quot;">​</a></h1><div class="epigraph"><p>带宽 $B$ 与信噪比把可靠速率钉死在 $C=B\\log_2(1+S/N)$；链路的波特、编码与重传都在这个上界下面找工程点。</p><footer>—— 据 Shannon, Communication in the Presence of Noise, Proc. IRE 1949；Nyquist, 1928 整理</footer></div><p><a href="/cs/socket-nonblock">上一课</a>把套接字分成阻塞与非阻塞：阻塞等就绪，非阻塞立即返回、靠多路复用再来，TCP 语义不变。主干网络已从<a href="/cs/layering-e2e">分层</a>走到<a href="/cs/socket-api">套接字</a>，帧与 MAC 当 PDU 用，还没有把一跳的比特率接到信息论。<a href="/cs/channel-capacity">信道容量</a>在离散 BSC 上给过 \\(C=\\max I(X;Y)\\)。缺口是<strong>链路上的香农公式</strong>：铜缆、光纤这一跳能可靠运送多少比特，后课调制与线路码都相对这个预算说话。后课默认已经读完本课。不重写 Transformer，不进限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教学五层把物理层写成「比特上介质」。介质有噪声、有限带宽。Nyquist：无噪声、\\(M\\) 电平、带宽 \\(B\\) 时符号率不超过 \\(2B\\)，比特率 \\(2B\\log_2 M\\)。Shannon：加性高斯噪声下 \\(C=B\\log_2(1+\\mathrm{SNR})\\)，与具体电平表无关。主干以太网课假定「链路有速率」；本课把速率还原成 \\(B\\) 与 SNR 的函数，而不是网卡说明书上的营销数字。</p><p>不要把 \\(C\\) 写成「已经达到的吞吐量」。吞吐是 MAC、队列与上层窗口之后的结果。</p><p><span class="marginnote">数字实例：一条 20 MHz 信道、SNR 为 30 dB（功率比 \\(10^{3}\\)），代入 \\(C=B\\log_2(1+S/N)\\) 得 \\(20\\times10^{6}\\times\\log_2 1001 \\approx 20\\text{M}\\times 9.97 \\approx 199\\) Mb/s——不管换多聪明的编码，这条信道的净信息率都超不过它。</span></p><p><span class="marginnote">Shannon 1948 给互信息容量；1949 年 IRE 文把带限高斯信道写成工程常用的 \\(B\\log(1+\\mathrm{SNR})\\)。Kurose and Ross 物理层章用同一公式对照拨号与以太网。本课不重证随机编码。</span></p><h3 id="容量不是标称速率" tabindex="-1">容量不是标称速率 <a class="header-anchor" href="#容量不是标称速率" aria-label="Permalink to &quot;容量不是标称速率&quot;">​</a></h3><p>网卡上的 Gb/s 已扣掉编码与 FEC，并且默认误码可忽略；那是工作点，不是 \\(C\\) 本身。后课调制与线路码都在这个预算下面移动，不改写香农公式。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一跳：给定频谱占用 \\(B\\)（电缆类别、光通道间隔）与可达到的 SNR（发射功率、衰减、接收机噪声系数）。\\(C\\) 是可靠速率上界。工程码（后课 8B/10B、FEC）用冗余换距离，使工作点低于 \\(C\\) 且错误可忽略。画：介质 → \\(B\\) 与 SNR → \\(C\\) → 再选调制阶数。</p>',12)),(s(),E(i,null,{default:o(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MED%5B%22%E4%BB%8B%E8%B4%A8%3A%20B%20%E4%B8%8E%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20C%5B%22C%20%3D%20B%20log(1%2BSNR)%22%5D%0A%20%20C%20--%3E%20MOD%5B%22%E9%80%89%E7%AC%A6%E5%8F%B7%E4%B8%8E%E7%A0%81%22%5D%0A%20%20MOD%20--%3E%20PHY%5B%22%E4%BD%8E%E4%BA%8E%20C%20%E7%9A%84%E5%8F%AF%E9%9D%A0%E9%80%9F%E7%8E%87%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,[e("主干"),n("a",{href:"/cs/frame-mac"},"帧"),e("的比特是已经判决后的符号流。判决之前，物理层必须先把波形放进 \\(B\\)，并对抗噪声。容量把「加冗余」从 CRC 检错升到：整条链路的净信息率不能超过 \\(C\\)。CRC 仍只覆盖一帧；容量管的是符号流的渐近可靠速率。")],-1)),a[5]||(a[5]=n("p",null,"与信息论课的分工：那里 \\(C\\) 是存在性；这里 \\(C\\) 是选电缆、光功率与 PAM 阶数时的预算。分离原理仍成立：链路 FEC 不必替 TCP 做端到端校验。",-1)),(s(),E(i,null,{default:o(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%83%B3%E6%8A%8A%E9%93%BE%E8%B7%AF%E9%80%9F%E7%8E%87%E5%BE%80%E4%B8%8A%E6%8A%AC%22%5D%20--%3E%20Q1%7B%22%E5%85%88%E5%8A%A0%E5%B8%A6%E5%AE%BD%20B%3F%22%7D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20L1%5B%22C%20%E9%9A%8F%20B%20%E7%BA%BF%E6%80%A7%E5%A2%9E%E9%95%BF%22%5D%0A%20%20L1%20--%3E%20R1%5B%22%E5%8F%97%E9%A2%91%E8%B0%B1%E8%AE%B8%E5%8F%AF%E4%B8%8E%E4%BB%8B%E8%B4%A8%E9%99%90%E5%88%B6%22%5D%0A%20%20G%20--%3E%20Q2%7B%22%E5%86%8D%E6%8F%90%20SNR%3F%22%7D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20L2%5B%22C%20%E6%8C%89%20log%20%E5%A2%9E%E9%95%BF%2C%20%E8%B6%8A%E6%8F%90%E8%B6%8A%E6%85%A2%22%5D%0A%20%20L2%20--%3E%20R2%5B%22%E5%8F%97%E5%8F%91%E5%B0%84%E5%8A%9F%E7%8E%87%E4%B8%8E%E5%99%AA%E5%A3%B0%E7%B3%BB%E6%95%B0%E9%99%90%E5%88%B6%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">直觉类比：SNR 那个对数项是「边际收益递减」——把发射功率翻一倍，\\(\\log_2(1+S/N)\\) 只多挣约 1 比特/赫兹；而带宽翻一倍，整个乘数直接翻倍。所以工程上宁可去抢频谱，也不靠无限堆功率。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ISI 均衡的抽头公式，不把 5G NR 的资源块当容量证明。也不把量化金融或 Transformer 注意力写成「信道」。后课默认：一跳的可靠速率以 \\(C\\) 为界；下一课用调制把 \\(C\\) 拆成符号率与每符号比特。</p><p>容量是互信息上界在带限链路上的实例，不是某款光模块的标称 Gb/s。标称速率已经含码开销与裕量。</p><p><span class="marginnote">常见误区：初学者容易把网卡标称速率当成香农容量。标称速率是扣掉 8B/10B、FEC 等码开销、又留了误码裕量之后的工作点，天然 \\lt \\(C\\)；真正的上界只由 \\(B\\) 与 SNR 决定，网卡说明书回答不了。</span></p><p>下一课<a href="/cs/modulation-symbol-rate">调制与符号率</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>链路预算：\\(C=B\\log_2(1+\\mathrm{SNR})\\)；Nyquist 管无噪声符号率。</li><li>帧里的比特是 \\(C\\) 之下的工程点，不是上界本身。</li><li>主干网络假定「有速率」；本课把速率接到 \\(B\\) 与噪声。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Shannon, 1949；Nyquist, 1928；Kurose and Ross。</li></ul>',8))])}const N=B(d,[["render",C]]);export{S as __pageData,N as default};
